-- VELSA — sincronizacion agosto (corte 2026-08-17 16:07) — 2302 deals
-- Espejo exacto: todas las etapas, empresa='velsa'. Sin guarda.
-- Al final refresca la MV para que el dashboard lo vea de una.

DROP TABLE IF EXISTS bkp_velsa_20260818;
CREATE TABLE bkp_velsa_20260818 AS
SELECT * FROM public.bitrix_webhook_leads WHERE empresa='velsa';

BEGIN;

ON CONFLICT (empresa, bitrix_id) DO UPDATE SET etapa = EXCLUDED.etapa, etapa_bitrix = EXCLUDED.etapa_bitrix, event = EXCLUDED.event, phone = EXCLUDED.phone, source = EXCLUDED.source, city = EXCLUDED.city, repeated = EXCLUDED.repeated, responsible = EXCLUDED.responsible, utm_source = EXCLUDED.utm_source, utm_medium = EXCLUDED.utm_medium, utm_campaign = EXCLUDED.utm_campaign, utm_content = EXCLUDED.utm_content, utm_term = EXCLUDED.utm_term, fecha_venta_subida = EXCLUDED.fecha_venta_subida, fecha_concretar = EXCLUDED.fecha_concretar, modificado_por = EXCLUDED.modificado_por, creado_por = EXCLUDED.creado_por, pipeline = EXCLUDED.pipeline, comentario = EXCLUDED.comentario, iniciado_el = EXCLUDED.iniciado_el, otro_proveedor = EXCLUDED.otro_proveedor, razon_descarte = EXCLUDED.razon_descarte, innegociable = EXCLUDED.innegociable, volver_a_llamar = EXCLUDED.volver_a_llamar, documentos_pendientes = EXCLUDED.documentos_pendientes, motivo_atc = EXCLUDED.motivo_atc, raw_query = EXCLUDED.raw_query, created_at = EXCLUDED.created_at, updated_at = NOW();

COMMIT;

REFRESH MATERIALIZED VIEW public.mv_indicadores_velsa_completo;

SELECT etapa_crm, COUNT(*) AS leads
FROM public.mv_indicadores_velsa_completo
WHERE fecha_creacion_date >= DATE '2026-08-01'
GROUP BY 1 ORDER BY 2 DESC;
